mentations using such values\\", and a registry whose purpose is interoperability should not mint digests a conforming verifier may be unable to read. The alphabets are enforced rather than assumed: base58btc excludes 0, O, I and l, and an earlier permissive pattern let three published examples carry digests that were not valid base58 at all. base58btc is RECOMMENDED, for consistency with `did:key` and `did:webvh`.","type":"string","minLength":16,"pattern":"^(z[1-9A-HJ-NP-Za-km-z]+|u[A-Za-z0-9_-]+)\$","examples":["zQmbWqxBEKC3P8tqsKc98xmWNzrzDtRLMiMPL8wBuTGsMnR"]},"ElectionState":{"title":"ElectionState","type":"string","enum":["registered","registration","voting","closed","tallied","cancelled"]},"Dealing":{"title":"Dealing","description":"A trustee\'s contribution to the election key: Feldman commitments to its polynomial, a proof of knowledge of the constant term, and one share per trustee sealed to that trustee\'s transport key (CONVENTIONS §9.6).","type":"object","additionalProperties":false,"required":["dealer","commitments","pok","shares"],"properties":{"dealer":{"\$ref":"#/\$defs/TrusteeIndex"},"commitments":{"type":"array","minItems":2,"maxItems":64,"items":{"\$ref":"#/\$defs/GroupElement"}},"pok":{"\$ref":"#/\$defs/SigmaProof"},"shares":{"type":"array","minItems":2,"maxItems":64,"items":{"\$ref":"#/\$defs/SealedShare"}}}},"SealedShare":{"title":"SealedShare","type":"object","additionalProperties":false,"required":["recipient","share"],"properties":{"recipient":{"\$ref":"#/\$defs/TrusteeIndex"},"share":{"\$ref":"#/\$defs/SealedPayload"}}},"SealedPayload":{"title":"SealedPayload","description":"Bytes sealed to a key: a random group element encrypted as `kem`, and the bytes under ChaCha20-Poly1305 with a key derived from it, multibase base58btc (CONVENTIONS §9.4).","type":"object","additionalProperties":false,"required":["kem","body"],"properties":{"kem":{"\$ref":"#/\$defs/ElGamalCiphertext"},"body":{"type":"string","minLength":2,"maxLength":131072,"pattern":"^z[1-9A-HJ-NP-Za-km-z]+\$"}}},"ElGamalCiphertext":{"title":"ElGamalCiphertext","description":"`(a, b) = (r·G, M + r·Y)` under the election key `Y` (CONVENTIONS §9.2).","type":"object","additionalProperties":false,"required":["a","b"],"properties":{"a":{"\$ref":"#/\$defs/GroupElement"},"b":{"\$ref":"#/\$defs/GroupElement"}}},"GroupElement":{"title":"GroupElement","description":"A Ristretto group element: its 32-byte compression, multibase base58btc. Never the identity (CONVENTIONS §9.1).","type":"string","minLength":2,"maxLength":64,"pattern":"^z[1-9A-HJ-NP-Za-km-z]+\$"},"TrusteeIndex":{"title":"TrusteeIndex","description":"A trustee\'s index: its position in the manifest\'s `trustees.dids`, counting from 1.","type":"integer","minimum":1,"maximum":64},"SigmaProof":{"title":"SigmaProof","description":"A non-interactive sigma proof as its challenge and response `(c, z)` (Schnorr or Chaum–Pedersen; CONVENTIONS §9.3).","type":"object","additionalProperties":false,"required":["c","z"],"properties":{"c":{"\$ref":"#/\$defs/GroupScalar"},"z":{"\$ref":"#/\$defs/GroupScalar"}}},"GroupScalar":{"title":"GroupScalar","description":"A scalar mod the Ristretto group order: 32 canonical little-endian bytes, multibase base58btc (CONVENTIONS §9.1).","type":"string","minLength":2,"maxLength":64,"pattern":"^z[1-9A-HJ-NP-Za-km-z]+\$"}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: responsePayloadSchemaJson,
);
